package com.salespunch360.mobile
import android.app.Application;import androidx.lifecycle.AndroidViewModel;import androidx.lifecycle.viewModelScope;import com.salespunch360.mobile.account.*;import com.salespunch360.mobile.data.*;import java.io.IOException;import java.util.UUID;import kotlinx.coroutines.flow.MutableStateFlow;import kotlinx.coroutines.flow.StateFlow;import kotlinx.coroutines.launch;import kotlinx.serialization.json.*
data class ReceiptInvoice(val id:String,val branchId:String,val customerId:String,val number:String,val outstanding:String)
data class ReceiptRow(val id:String,val number:String,val date:String,val amount:String,val mode:String)
data class ReceiptState(val loading:Boolean=true,val saving:Boolean=false,val customers:List<SalesOption> = emptyList(),val branches:List<SalesOption> = emptyList(),val moneyAccounts:List<SalesOption> = emptyList(),val invoices:List<ReceiptInvoice> = emptyList(),val history:List<ReceiptRow> = emptyList(),val branchId:String="",val customerId:String="",val invoiceId:String="",val amount:String="",val date:String=java.time.LocalDate.now().toString(),val mode:String="BANK",val moneyAccountId:String="",val reference:String="",val notes:String="",val error:String?=null,val message:String?=null)
class CustomerReceiptViewModel(app:Application):AndroidViewModel(app){private val api=ApiClient(SecureSession(app));private val _state=MutableStateFlow(ReceiptState());val state:StateFlow<ReceiptState> = _state;init{refresh()};fun refresh()=viewModelScope.launch{_state.value=_state.value.copy(loading=true,error=null);try{val x=api.customerReceiptContext(),branches=x.array("branches").map{it.option()},customers=x.array("customers").map{it.option()},accounts=x.array("moneyAccounts").map{it.option()},docs=x.array("documents").map{ReceiptInvoice(it.str("id"),it.str("branchId"),it.str("customerId"),it.str("documentNumber"),it.str("outstanding"))},history=x.array("receipts").map{ReceiptRow(it.str("id"),it.str("settlementNumber"),it.str("transactionDate").take(10),it.str("amount"),it.str("paymentMode"))};_state.value=_state.value.copy(loading=false,branches=branches,customers=customers,moneyAccounts=accounts,invoices=docs,history=history,branchId=_state.value.branchId.ifBlank{branches.firstOrNull()?.id.orEmpty()})}catch(e:Exception){_state.value=_state.value.copy(loading=false,error=errorText(e))}};fun update(transform:(ReceiptState)->ReceiptState){_state.value=transform(_state.value)};fun save()=viewModelScope.launch{val s=_state.value,amount=s.amount.toDoubleOrNull();if(amount==null||amount<=0||s.invoiceId.isBlank()){_state.value=s.copy(error="Select an invoice and enter a positive amount.");return@launch};_state.value=s.copy(saving=true,error=null);try{api.createCustomerReceipt(buildJsonObject{put("idempotencyKey",UUID.randomUUID().toString());put("type","CUSTOMER_RECEIPT");put("branchId",s.branchId);put("partyId",s.customerId);put("paymentMode",s.mode);s.moneyAccountId.takeIf{it.isNotBlank()}?.let{put("moneyAccountId",it)};put("amount",s.amount);put("transactionDate",s.date);put("reference",s.reference);put("notes",s.notes);putJsonArray("allocations"){add(buildJsonObject{put("documentId",s.invoiceId);put("amount",s.amount)})}});_state.value=s.copy(saving=false,amount="",invoiceId="",message="Customer receipt posted by the server.");refresh()}catch(e:Exception){_state.value=s.copy(saving=false,error=errorText(e))}};private fun errorText(e:Exception)=when{e is IOException->"You're offline. The receipt was not posted.";e is ApiException&&e.status==403->"You are not authorized to receive this payment.";else->"The server rejected this receipt or allocation."}}
